[checks/wal_diff_demo.py]
BEGIN WalStore.diff demo
INPUT commit 1: account=100, profile={active: true}; RESPONSE seq=1 state={'account': 100, 'profile': {'active': True}}
INPUT commit 2: delete account, update profile; RESPONSE seq=2 state={'profile': {'active': False, 'tags': ['vip']}}
OBSERVE diff(1,2): {"changes": [{"key": "account", "op": "delete"}, {"key": "profile", "op": "set", "value": {"active": false, "tags": ["vip"]}}], "from_seq": 1, "to_seq": 2}
OBSERVE pending_changes(): {"changes": [{"key": "pending", "op": "set", "value": {"x": [1]}}], "commit_seq": 2, "pending_count": 1}
OBSERVE diff(2,2) excludes pending: {"changes": [], "from_seq": 2, "to_seq": 2}
OBSERVE reopened diff(1,2): {"changes": [{"key": "account", "op": "delete"}, {"key": "profile", "op": "set", "value": {"active": false, "tags": ["vip"]}}], "from_seq": 1, "to_seq": 2}
END WalStore.diff demo
BEGIN WalStore.diff boundary demo
INPUT empty diff(0,0): {"changes": [], "from_seq": 0, "to_seq": 0}
OUTPUT empty diff(0,1): ValueError: to_seq 1 exceeds latest committed seq 0
OUTPUT closed diff("bad",-1): WalClosedError: WalStore is closed
INPUT recoverable tail; RESPONSE diff(0,1): {"changes": [{"key": "stable", "op": "set", "value": 1}], "from_seq": 0, "to_seq": 1}
INPUT append after diff: next=2; RESPONSE commit_seq=2 state={'stable': 1, 'next': 2}
OUTPUT invalid form before corruption read: ValueError: from_seq must be a non-negative integer, got -1
OUTPUT terminated corruption: WalCorruptionError: bad fields for op 'set': ['key', 'op']
END WalStore.diff boundary demo

